mapper.delete:
delete from sys_bookshelf_record
where user_id = #{userId}
  and work_id = #{workId}

mapper.select:
select count(1)
from sys_bookshelf_record
where user_id = #{userId}
  and work_id = #{workId}

mapper.update:
update sys_bookshelf_record
set last_read_chapter_id = #{chapterId},
    last_read_at = now(),
    updated_at = now()
where user_id = #{userId}
  and work_id = #{workId}
